    this.heartbeatIntervalSeconds = intervalSeconds;
    this.heartbeatRecheckInterval = recheckInterval;
    this.heartbeatExpireInterval = 2L * recheckInterval + 10 * 1000
        * intervalSeconds;
    this.blockInvalidateLimit = getBlockInvalidateLimit(blockInvalidateLimit);
  }

  private void initBlockInvalidateLimit(Configuration conf) {
    setBlockInvalidateLimit(conf.getInt(
        DFSConfigKeys.DFS_BLOCK_INVALIDATE_LIMIT_KEY,
        DFSConfigKeys.DFS_BLOCK_INVALIDATE_LIMIT_DEFAULT));
  }

  /**
   * Effected block invalidate limit is the bigger value between the
   * configured limit and 20 * HB interval.
   *
   * @param configuredBlockInvalidateLimit block invalidate limit as
   *                                       provided by the config.
   * @return the effected block invalidate limit.
   */
  private int getBlockInvalidateLimit(int configuredBlockInvalidateLimit) {
    return Math.max(getBlockInvalidateLimitFromHBInterval(),
        configuredBlockInvalidateLimit);
  }

  /**
   * @return block invalidate limit as counted from the heartbeat interval.
   */
  private int getBlockInvalidateLimitFromHBInterval() {
    return 20 * (int) heartbeatIntervalSeconds;
  }

  /**
   * Set the maximum number of blocks a DataNode is asked to delete with
   * one heartbeat response, i.e. reconfigure
   * {@link DFSConfigKeys#DFS_BLOCK_INVALIDATE_LIMIT_KEY}.
   *
   * @param configuredBlockInvalidateLimit block invalidate limit as
   *                                       provided by the config.
   */
  public void setBlockInvalidateLimit(int configuredBlockInvalidateLimit) {
    this.blockInvalidateLimit =
        getBlockInvalidateLimit(configuredBlockInvalidateLimit);
    LOG.info("{} : configured={}, counted={}, effected={}",
        DFSConfigKeys.DFS_BLOCK_INVALIDATE_LIMIT_KEY,
        configuredBlockInvalidateLimit,
        getBlockInvalidateLimitFromHBInterval(), this.blockInvalidateLimit);
  }
